begin;
-- Owner requested the existing real-estate listings to be visible again.
-- Restore only the four historical public portfolio briefs, without asserting
-- current availability, pricing or an active mandate. Never publish newer drafts.
lock table public.ig_content, public.ig_public_content in share row exclusive mode;
do $release$
declare source jsonb; item public.ig_content; restored integer=0;
begin
 for source in select value from jsonb_array_elements('[{"body":"A hospitality structure featured in India Gully’s existing portfolio, with development and fit-out considerations to review.\n\nThis reference is carried forward from the existing India Gully portfolio. Please contact our team to verify current availability and mandate status.","kind":"opportunity","slug":"heritage-hotel-jaipur","tags":[],"title":"Heritage Hotel Structure","summary":"A hospitality structure featured in India Gully’s existing portfolio, with development and fit-out considerations to review.","practice":"real-estate","seo_title":"Heritage Hotel Structure","source_id":"0fe29ef8-865e-4694-bfea-aa97d67c5e98","public_data":{"city":"Jaipur","sector":"Hospitality","image_alt":"Heritage Hotel Structure","reference":"Portfolio reference","asset_class":"Hospitality development"},"source_version":2,"seo_description":"A hospitality structure featured in India Gully’s existing portfolio, with development and fit-out considerations to review."},{"body":"A hotel and spa opportunity featured in India Gully’s existing hospitality portfolio.\n\nThis reference is carried forward from the existing India Gully portfolio. Please contact our team to verify current availability and mandate status.","kind":"opportunity","slug":"hotel-rajshree-chandigarh","tags":[],"title":"Hotel Rajshree & Spa","summary":"A hotel and spa opportunity featured in India Gully’s existing hospitality portfolio.","practice":"real-estate","seo_title":"Hotel Rajshree & Spa","source_id":"df7eab84-93ff-4102-9187-ffa3dbde1aa7","public_data":{"city":"Chandigarh","image":"/images/rajshree.webp","sector":"Hospitality","image_alt":"Hotel Rajshree & Spa","reference":"Portfolio reference","asset_class":"Hotel & wellness"},"source_version":1,"seo_description":"A hotel and spa opportunity featured in India Gully’s existing hospitality portfolio."},{"body":"A commercial and hospitality asset featured in India Gully’s existing opportunity portfolio.\n\nThis reference is carried forward from the existing India Gully portfolio. Please contact our team to verify current availability and mandate status.","kind":"opportunity","slug":"prism-tower-gurgaon","tags":[],"title":"Prism Tower","summary":"A commercial and hospitality asset featured in India Gully’s existing opportunity portfolio.","practice":"real-estate","seo_title":"Prism Tower","source_id":"3a7bcf57-2df3-45bc-a2aa-345efbe86c6c","public_data":{"city":"Gurugram","image":"/images/prism.jpg","sector":"Commercial","image_alt":"Prism Tower","reference":"Portfolio reference","asset_class":"Mixed-use commercial & hospitality"},"source_version":1,"seo_description":"A commercial and hospitality asset featured in India Gully’s existing opportunity portfolio."},{"body":"A resort asset featured in India Gully’s existing hospitality opportunity portfolio.\n\nThis reference is carried forward from the existing India Gully portfolio. Please contact our team to verify current availability and mandate status.","kind":"opportunity","slug":"welcomheritage-santa-roza-kasauli","tags":[],"title":"Santa Roza, Kasauli","summary":"A resort asset featured in India Gully’s existing hospitality opportunity portfolio.","practice":"real-estate","seo_title":"Santa Roza, Kasauli","source_id":"46ddc493-4a4a-4f3b-8016-8070819c2081","public_data":{"city":"Kasauli","image":"/images/kasauli.jpg","sector":"Hospitality","image_alt":"Santa Roza, Kasauli","reference":"Portfolio reference","asset_class":"Hill resort"},"source_version":1,"seo_description":"A resort asset featured in India Gully’s existing hospitality opportunity portfolio."}]'::jsonb) loop
  select * into item from public.ig_content where kind='opportunity' and slug=source->>'slug' for update;
  if item.id is null or item.version<>1 or item.status<>'draft' or item.published_version is not null
   or item.title is distinct from source->>'title' or item.body is distinct from source->>'body'
   or item.public_data is distinct from source->'public_data' then
   raise exception 'Portfolio reference changed; review instead of overwriting: %',source->>'slug';
  end if;
  if item.public_data->>'reference'<>'Portfolio reference' or item.body not like '%verify current availability and mandate status%' then raise exception 'Required portfolio disclosure missing'; end if;
  insert into public.ig_public_content(id,kind,slug,title,summary,body,seo_title,seo_description,public_data,version)
   values(item.id,item.kind,item.slug,item.title,item.summary,item.body,item.seo_title,item.seo_description,item.public_data,item.version);
  update public.ig_content set status='published',published_version=version where id=item.id;
  insert into public.ig_audit(action,entity_id,detail) values('deployment.portfolio_reference_restored',item.id::text,
   jsonb_build_object('version',item.version,'reason','Owner requested missing listings; existing public portfolio reference restored with availability and mandate caveat','source_release','production-content-release.json','mechanism','Authorised deployment; no user impersonation','current_availability_confirmed',false));
  restored=restored+1;
 end loop;
 if restored<>4 then raise exception 'Expected exactly four existing references'; end if;
end $release$;
select slug,title,version from public.ig_public_content where kind='opportunity' order by slug;
commit;
